const money = n => '\u09F3 ' + Number(n).toLocaleString('en-BD');
const escapeHtml = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function stabilizeSelectValues(root){root.querySelectorAll('select option:not([value])').forEach(option=>{option.value=option.textContent.trim()})}
const statusClass = s => 'status-' + s.toLowerCase();
const initial = (name) => name.split(' ').map(x=>x[0]).slice(0,2).join('');
const appView=document.querySelector('#app-view'),loginView=document.querySelector('#login-view'),pageContent=document.querySelector('#page-content');
let toastTimer;
function notify(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function logout(){localStorage.removeItem('probashiSignedIn');appView.classList.add('hidden');loginView.classList.remove('hidden')}
function enterApp(){loginView.classList.add('hidden');appView.classList.remove('hidden');renderPage(location.hash.slice(1)||'dashboard')}
document.querySelector('#login-form').addEventListener('submit',e=>{e.preventDefault();const email=document.querySelector('#email').value.trim().toLowerCase(),password=document.querySelector('#password').value,error=document.querySelector('#form-error');if(email==='admin@probashi.store'&&password==='probashi123'){error.textContent='';localStorage.setItem('probashiSignedIn','true');enterApp()}else error.textContent='These details do not match the demo workspace. Use the prefilled demo login.'});
document.querySelector('.password-toggle').addEventListener('click',e=>{const input=document.querySelector('#password'),show=input.type==='password';input.type=show?'text':'password';e.currentTarget.setAttribute('aria-label',show?'Hide password':'Show password')});
document.querySelector('#forgot-link').addEventListener('click',e=>{e.preventDefault();notify('Please contact your store administrator to reset your password.')});document.querySelector('#help-link').addEventListener('click',e=>{e.preventDefault();notify('Support: hello@probashi.store')});
const fmtDate=new Intl.DateTimeFormat('en',{weekday:'long',month:'long',day:'numeric'});const headingSubtitle=`Here’s what’s happening with your store today.`;
function metric(icon,label,value,detail,change=''){return `<article class="metric-card"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-foot">${change?`<span class="change-up">${change}</span>`:''}${detail}</div></article>`}
const icons={sales:'<svg viewBox="0 0 20 20"><path d="M3 15.5 7 11l3 2 6-7"/><path d="M12 6h4v4"/></svg>',orders:'<svg viewBox="0 0 20 20"><path d="M4 3.5h12v14l-2-1.4-2 1.4-2-1.4-2 1.4-2-1.4-2 1.4v-14Z"/><path d="M7 7h6m-6 3h6"/></svg>',customers:'<svg viewBox="0 0 20 20"><circle cx="7.5" cy="6" r="3"/><path d="M2.5 16a5 5 0 0 1 10 0m2-7a3 3 0 0 0 0-6m1 8a4 4 0 0 1 2 4"/></svg>',average:'<svg viewBox="0 0 20 20"><path d="M10 2.5v15M14 6H8a2.5 2.5 0 0 0 0 5h4a2.5 2.5 0 0 1 0 5H5"/></svg>'};
function salesChart(){return `<div class="chart-legend"><span><i class="legend-dot"></i>Revenue</span><span><i class="legend-dot light"></i>Previous period</span></div><div class="chart-wrap"><svg viewBox="0 0 700 190" preserveAspectRatio="none" aria-label="Revenue trend chart"><defs><linearGradient id="areaFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#c6a14a" stop-opacity=".2"/><stop offset="100%" stop-color="#c6a14a" stop-opacity="0"/></linearGradient></defs><path class="chart-grid" d="M0 20H700M0 62H700M0 104H700M0 146H700"/><path d="M0 129C45 120 47 142 91 117S144 117 181 91s54 16 92-2 54 8 92-20 61 20 103-2 54-5 93-34 57 2 87-14 34 4 52-8V170H0Z" fill="#eee9db" opacity=".48"/><path class="chart-area" d="M0 143C42 135 48 121 88 128s51-40 92-27 51-8 89-5 54-40 94-28 53 10 92-13 53 16 94-11 57-6 91-19 39 0 60-12V170H0Z"/><path class="chart-line" d="M0 143C42 135 48 121 88 128s51-40 92-27 51-8 89-5 54-40 94-28 53 10 92-13 53 16 94-11 57-6 91-19 39 0 60-12"/><circle class="chart-dot" cx="549" cy="55" r="4"/><circle class="chart-dot" cx="700" cy="13" r="4"/></svg></div><div class="chart-labels"><span>Sep 15</span><span>Sep 22</span><span>Sep 29</span><span>Oct 06</span><span>Oct 14</span></div>`}
function orderTable(rows,limit=Infinity,showActions=false){const data=rows.slice(0,limit);if(!data.length)return `<div class="empty-state"><strong>No orders found</strong>Try changing your search or filters.</div>`;return `<table class="data-table"><thead><tr><th>ORDER</th><th>CUSTOMER</th><th>DATE</th><th>ITEMS</th><th>TOTAL</th><th>STATUS</th>${showActions?'<th></th>':''}</tr></thead><tbody>${data.map(o=>{const index=orders.indexOf(o);return `<tr><td class="order-id">${escapeHtml(o.id)}</td><td><div class="customer-cell"><span class="customer-avatar" style="background:${escapeHtml(o.color)}">${escapeHtml(o.initials)}</span><span><b>${escapeHtml(o.name)}</b><small>${escapeHtml(o.email)}</small></span></div></td><td>${escapeHtml(o.date)}</td><td>${o.items} ${o.items===1?'item':'items'}</td><td>${money(o.total)}</td><td><span class="status-pill ${statusClass(o.status)}">${escapeHtml(o.status)}</span></td>${showActions?`<td><button class="order-edit-button" data-action="edit-order" data-index="${index}"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m13.5 3.5 3 3M4 16l3.6-.7L16 7a2.12 2.12 0 0 0-3-3l-8.4 8.4L4 16Z"/></svg><span>Edit</span></button></td>`:''}</tr>`}).join('')}</tbody></table>`}
function dashboard(){const salesOrders=orders.filter(o=>o.status!=='Cancelled'),orderValue=salesOrders.reduce((sum,o)=>sum+Number(o.total||0),0),customerCount=new Set(salesOrders.map(o=>o.email)).size,average=salesOrders.length?Math.round(orderValue/salesOrders.length):0,counts=Object.fromEntries(['Delivered','Shipped','Pending','Cancelled'].map(s=>[s,orders.filter(o=>o.status===s).length])),total=orders.length,ring=`conic-gradient(#d4a22c 0 ${total?counts.Delivered/total*100:0}%,#355b62 ${total?counts.Delivered/total*100:0}% ${total?(counts.Delivered+counts.Shipped)/total*100:0}%,#d9d4c5 ${total?(counts.Delivered+counts.Shipped)/total*100:0}% ${total?(counts.Delivered+counts.Shipped+counts.Pending)/total*100:0}%,#eeeae0 ${total?(counts.Delivered+counts.Shipped+counts.Pending)/total*100:0}% 100%)`;return `<div class="page-heading"><div><span class="section-kicker">STORE OVERVIEW · DEMO FIGURES</span><h1>Good morning, Payar <span style="font-size:21px">☀️</span></h1><p>Preview the workspace with sample store records.</p></div><div class="heading-actions"><button class="button-secondary" data-action="export"><svg viewBox="0 0 20 20"><path d="M10 3v9m-3-3 3 3 3-3M4 14v3h12v-3"/></svg>Export report</button><button class="button-primary" data-action="new-order"><svg viewBox="0 0 20 20"><path d="M10 4v12M4 10h12"/></svg>New order</button></div></div><section class="metrics-grid">${metric(icons.sales,'Sample order value',money(orderValue),'across demo orders')}${metric(icons.orders,'Sample orders',total,'stored in this browser')}${metric(icons.customers,'Customers in sample',customerCount,'unique demo records')}${metric(icons.average,'Average order value',money(average),'from sample orders')}</section><section class="dashboard-grid"><article class="panel sales-panel"><div class="panel-heading"><div><h3>Sales overview</h3><p>Illustrative trend · connect real sales data later</p></div><select class="period-select" id="chart-period" aria-label="Chart period"><option>This week</option><option selected>This month</option><option>This year</option></select></div><div id="chart-area">${salesChart()}</div></article><article class="panel order-summary"><div class="panel-heading"><div><h3>Order status</h3><p>Breakdown of sample orders</p></div><button class="icon-button" data-action="orders" aria-label="View orders">↗</button></div><div class="summary-total"><strong>${total}</strong><span>sample orders</span></div><div class="ring-wrap"><div class="donut" style="background:${ring}"><div class="donut-center"><strong>${total}</strong><small>ORDERS</small></div></div><div class="order-legend"><span><i></i>Delivered <b>${counts.Delivered}</b></span><span><i></i>Shipped <b>${counts.Shipped}</b></span><span><i></i>Pending <b>${counts.Pending}</b></span><span><i></i>Cancelled <b>${counts.Cancelled}</b></span></div></div><div class="summary-bottom"><span>Sample records</span><strong>${total?`${counts.Delivered} delivered`:'No orders yet'}</strong></div></article></section><section class="panel table-panel"><div class="table-title"><h3>Recent orders</h3><a href="#orders" class="text-link">View all orders →</a></div>${orderTable(orders,5)}<div class="table-footer"><span>Showing ${Math.min(orders.length,5)} of ${orders.length} sample orders</span><span>Demo data</span></div></section>`}
function ordersPage(){const count=s=>orders.filter(o=>s==='All orders'||o.status===s).length;return `<div class="page-heading"><div><span class="section-kicker">SALES MANAGEMENT</span><h1>Orders</h1><p>Follow every purchase from checkout to delivery.</p></div><div class="heading-actions"><button class="button-secondary" data-action="export"><svg viewBox="0 0 20 20"><path d="M10 3v9m-3-3 3 3 3-3M4 14v3h12v-3"/></svg>Export</button><button class="button-primary" data-action="new-order"><svg viewBox="0 0 20 20"><path d="M10 4v12M4 10h12"/></svg>New order</button></div></div><section class="status-overview">${[['All orders',orders.length],['Pending',count('Pending')],['Shipped',count('Shipped')],['Delivered',count('Delivered')]].map(([label,num],i)=>`<button class="status-tile ${i===0?'selected':''}" data-status-shortcut="${i===0?'':label}"><span>${label}</span><strong>${num.toString().padStart(2,'0')}</strong><i></i></button>`).join('')}</section><div class="panel table-panel orders-list-panel"><div class="list-toolbar"><div><h3>All transactions</h3><p>Your latest customer purchases</p></div><div class="filter-row"><label class="search-box"><svg viewBox="0 0 20 20"><circle cx="8.5" cy="8.5" r="5.5"/><path d="m13 13 4 4"/></svg><input id="order-search" placeholder="Order, name, or email"></label><select id="status-filter" class="filter-select"><option value="">Every status</option>${['Paid','Pending','Shipped','Delivered','Cancelled'].map(s=>`<option>${s}</option>`).join('')}</select></div></div><div id="orders-table">${orderTable(orders,Infinity,true)}<div class="table-footer"><span id="order-count">${orders.length} sample orders shown</span><span>Demo records · all dates</span></div></div></section>`}
function productsPage(){const active=products.filter(p=>p.active!==false),archived=products.filter(p=>p.active===false),low=active.filter(p=>Number(p.stock)<10).length,value=active.reduce((sum,p)=>sum+Number(p.price)*Number(p.stock),0);return `<div class="page-heading"><div><span class="section-kicker">CATALOGUE</span><h1>Products & inventory</h1><p>Keep your collection, prices, and stock in one place.</p></div><button class="button-primary" data-action="add-product"><svg viewBox="0 0 20 20"><path d="M10 4v12M4 10h12"/></svg>Add product</button></div><section class="inventory-overview"><article class="inventory-stat"><span class="stat-glyph">◈</span><div><small>Listed products</small><strong>${active.length.toString().padStart(2,'0')}</strong></div><span class="stat-note">across your catalogue</span></article><article class="inventory-stat"><span class="stat-glyph warning">!</span><div><small>Needs restocking</small><strong>${low.toString().padStart(2,'0')}</strong></div><span class="stat-note">less than 10 units</span></article><article class="inventory-stat"><span class="stat-glyph">৳</span><div><small>Stock value</small><strong>${money(value)}</strong></div><span class="stat-note">active products</span></article></section><section class="panel catalogue-panel"><div class="list-toolbar"><div><h3>Your catalogue <span class="subtle-count">${active.length}</span></h3><p>${archived.length?`${archived.length} archived products`: 'Product cards show current stock at a glance.'}</p></div><div class="filter-row"><label class="search-box"><svg viewBox="0 0 20 20"><circle cx="8.5" cy="8.5" r="5.5"/><path d="m13 13 4 4"/></svg><input id="product-search" placeholder="Find a product"></label><select id="category-filter" class="filter-select"><option value="">All categories</option>${[...new Set(products.map(p=>p.category))].map(c=>`<option>${escapeHtml(c)}</option>`).join('')}</select><select id="stock-filter" class="filter-select"><option value="">Active products · any stock</option><option value="low">Low stock</option><option value="available">In stock</option><option value="empty">Out of stock</option><option value="archived">Archived products (${archived.length})</option></select></div></div><section class="simple-grid" id="product-grid">${productCards(active)}</section></section>`}function productCards(list){return list.length?list.map(p=>{const index=products.indexOf(p),low=Number(p.stock)<10,pct=Math.min(100,Math.max(4,Number(p.stock)*2)),archived=p.active===false;return `<article class="panel product-card ${archived?'is-archived':''}"><div class="product-art"><span>${escapeHtml(p.icon||'□')}</span><button class="product-edit" data-action="edit-product" data-index="${index}" aria-label="Edit ${escapeHtml(p.name)}">•••</button></div><div class="product-card-body"><span class="category-chip">${escapeHtml(p.category)}</span>${archived?'<span class="archived-badge">Archived</span>':''}<h3>${escapeHtml(p.name)}</h3><div class="product-meta"><span>${money(p.price)}</span><span class="stock-label ${low?'low':''}">${low?'Restock soon':`${p.stock} units`}</span></div><div class="stock-track"><i class="${low?'low':''}" style="width:${pct}%"></i></div><div class="product-card-actions"><button class="product-edit-link" data-action="edit-product" data-index="${index}">Edit product <span>↗</span></button><button class="product-archive-link" data-action="${archived?'restore-product':'archive-product'}" data-index="${index}">${archived?'Restore':'Archive'}</button></div></div></article>`}).join(''):`<article class="panel empty-state" style="grid-column:1/-1"><strong>No products found</strong>Try another filter or add a new product.</article>`}function customersPage(){const repeats=customers.filter((_,i)=>i%2).length;return `<div class="page-heading"><div><span class="section-kicker">PEOPLE · SAMPLE RECORDS</span><h1>Customers</h1><p>Browse the customer records included in this demo.</p></div><button class="button-secondary" data-action="export"><svg viewBox="0 0 20 20"><path d="M10 3v9m-3-3 3 3 3-3M4 14v3h12v-3"/></svg>Export orders</button></div><section class="summary-cards"><article class="panel summary-card"><small>Customer records</small><strong>${customers.length}</strong></article><article class="panel summary-card"><small>Repeat buyers in sample</small><strong>${repeats}</strong></article><article class="panel summary-card"><small>Orders across this list</small><strong>${customers.reduce((sum,c)=>sum+c[3],0)}</strong></article></section><section class="panel table-panel"><div class="table-title"><h3>Customer directory <span class="subtle-count">${customers.length} demo records</span></h3></div><table class="data-table"><thead><tr><th>CUSTOMER</th><th>LAST ORDER</th><th>ORDERS</th><th>LIFETIME SPEND</th><th>TYPE</th></tr></thead><tbody>${customers.map((c,i)=>`<tr><td><div class="customer-cell"><span class="customer-avatar">${initial(c[0])}</span><span><b>${escapeHtml(c[0])}</b><small>${escapeHtml(c[1])}</small></span></div></td><td>${escapeHtml(c[2])}</td><td>${c[3]}</td><td>${escapeHtml(c[4])}</td><td><span class="status-pill ${i%2?'status-paid':'status-pending'}">${i%2?'Returning':'Regular'}</span></td></tr>`).join('')}</tbody></table><div class="table-footer"><span>Showing ${customers.length} sample customers</span><span>Demo data</span></div></section>`}
function expensesPage(){const total=expenses.reduce((sum,x)=>sum+Number(x.amount),0),largest=expenses.reduce((a,b)=>Number(a.amount)>Number(b.amount)?a:b,expenses[0]);return `<div class="page-heading"><div><span class="section-kicker">CASH FLOW</span><h1>Expenses</h1><p>Record the everyday costs behind your store.</p></div><button class="button-primary" data-action="add-expense"><svg viewBox="0 0 20 20"><path d="M10 4v12M4 10h12"/></svg>Add expense</button></div><section class="expense-overview"><article class="expense-total-card"><span class="expense-overline">TOTAL RECORDED · DEMO DATA</span><strong>${money(total)}</strong><span class="expense-foot">${expenses.length} entries in this sample</span><div class="expense-watermark">৳</div></article><article class="expense-insight"><span class="insight-icon">↗</span><small>Largest recorded cost</small><strong>${largest?escapeHtml(largest.description):'No expenses yet'}</strong><span>${largest?money(largest.amount):'Add your first expense'}</span></article><article class="expense-insight"><span class="insight-icon">◷</span><small>Common categories</small><strong>${[...new Set(expenses.map(x=>x.category))].length}</strong><span>across your entries</span></article></section><section class="panel expense-list-panel"><div class="list-toolbar"><div><h3>Expense ledger</h3><p>Use the category filter to narrow your view.</p></div><div class="filter-row"><label class="search-box"><svg viewBox="0 0 20 20"><circle cx="8.5" cy="8.5" r="5.5"/><path d="m13 13 4 4"/></svg><input id="expense-search" placeholder="Search expenses"></label><select id="expense-category" class="filter-select"><option value="">All categories</option>${[...new Set(expenses.map(x=>x.category))].map(c=>`<option>${escapeHtml(c)}</option>`).join('')}</select></div></div><div id="expense-table">${expenseTable(expenses)}</div></section>`}
function expenseTable(rows){return rows.length?`<table class="data-table"><thead><tr><th>EXPENSE</th><th>CATEGORY</th><th>DATE</th><th>PAYMENT</th><th>AMOUNT</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><span class="expense-name"><i>↗</i><b>${escapeHtml(r.description)}</b></span></td><td><span class="category-chip">${escapeHtml(r.category)}</span></td><td>${escapeHtml(r.date)}</td><td>${escapeHtml(r.method)}</td><td class="expense-amount">${money(r.amount)}</td><td class="expense-actions"><button class="row-action" data-action="edit-expense" data-index="${expenses.indexOf(r)}">Edit</button><button class="row-action danger-action" data-action="delete-expense" data-index="${expenses.indexOf(r)}">Delete</button></td></tr>`).join('')}</tbody></table>`:`<div class="empty-state"><strong>No expenses match</strong>Try another search or record a new expense.</div>`}function reportsPage(){const orderValue=orders.reduce((sum,o)=>sum+Number(o.total||0),0),expensesValue=expenses.reduce((sum,x)=>sum+Number(x.amount||0),0),units=products.filter(p=>p.active!==false).reduce((sum,p)=>sum+Number(p.stock||0),0);return `<div class="page-heading"><div><span class="section-kicker">INSIGHTS · SAMPLE DATA</span><h1>Reports</h1><p>A visual preview of the numbers currently stored in this browser.</p></div><button class="button-secondary" data-action="export"><svg viewBox="0 0 20 20"><path d="M10 3v9m-3-3 3 3 3-3M4 14v3h12v-3"/></svg>Export orders</button></div><section class="metrics-grid">${metric(icons.sales,'Sample order value',money(orderValue),'sum of listed orders')}${metric(icons.orders,'Orders listed',orders.length,'demo records')}${metric(icons.average,'Expenses recorded',money(expensesValue),'demo entries')}${metric(icons.customers,'Units in stock',units,'listed products')}</section><section class="panel sales-panel report-preview" style="margin-top:16px"><div class="panel-heading"><div><h3>Illustrative sales trend</h3><p>Sample visual only · this is not a live sales report</p></div><span class="category-chip">DEMO PREVIEW</span></div>${salesChart()}</section>`}
function settingsPage(){return `<div class="page-heading"><div><h1>Settings</h1><p>Manage your store preferences and account.</p></div></div><section class="panel settings-panel"><h3>Store profile</h3><p>Update the details customers see about your business.</p><div class="settings-row"><span><b>Store name</b><small>Your public business name</small></span><input value="${escapeHtml(storeSettings.storeName)}" aria-label="Store name" required></div><div class="settings-row"><span><b>Contact email</b><small>Order notifications and support</small></span><input type="email" value="${escapeHtml(storeSettings.contactEmail)}" aria-label="Contact email" required></div><div class="settings-row"><span><b>Currency</b><small>Used for prices and reports</small></span><select aria-label="Currency"><option value="BDT" ${storeSettings.currency==='BDT'?'selected':''}>Bangladeshi Taka (৳ BDT)</option></select></div><div class="settings-row"><span><b>Timezone</b><small>Used for order dates and reports</small></span><select aria-label="Timezone"><option value="Asia/Dhaka" ${storeSettings.timezone==='Asia/Dhaka'?'selected':''}>Asia/Dhaka (GMT+6)</option></select></div><div style="display:flex;justify-content:flex-end;padding-top:17px"><button class="button-primary" data-action="save-settings">Save changes</button></div></section>`}
let purchases=[];try{const saved=JSON.parse(localStorage.getItem('probashi-purchases'));if(Array.isArray(saved))purchases=saved}catch{}
let accountBalances={cash:0,bank:0};try{accountBalances={...accountBalances,...JSON.parse(localStorage.getItem('probashi-balances')||'{}')}}catch{}
let storeSettings={storeName:'Probashi Store',contactEmail:'hello@probashi.store',currency:'BDT',timezone:'Asia/Dhaka'};try{storeSettings={...storeSettings,...JSON.parse(localStorage.getItem('probashi-store-settings')||'{}'),storeName:localStorage.getItem('probashi-store-name')||JSON.parse(localStorage.getItem('probashi-store-settings')||'{}').storeName||'Probashi Store'}}catch{}
const baseProductsPage=productsPage;productsPage=function(){const html=baseProductsPage(),tracked=products.filter(p=>p.active!==false&&(p.barcode||p.expiry));return html.replace('<section class="panel catalogue-panel"',`${tracked.length?`<section class="panel table-panel feature-table"><div class="table-title"><h3>Barcode & expiry tracking</h3><span class="subtle-count">${products.filter(p=>p.active!==false&&p.expiry&&p.expiry<=todayISO()).length} expired · ${products.filter(p=>p.active!==false&&p.expiry&&p.expiry>todayISO()&&p.expiry<new Date(Date.now()+30*86400000).toISOString().slice(0,10)).length} expiring soon</span></div><table class="data-table"><thead><tr><th>PRODUCT</th><th>BARCODE</th><th>EXPIRY</th><th>STATUS</th></tr></thead><tbody>${tracked.map(p=>`<tr><td>${escapeHtml(p.name)}</td><td>${escapeHtml(p.barcode||'—')}</td><td>${escapeHtml(p.expiry||'—')}</td><td>${p.expiry?(p.expiry<todayISO()?'Expired':p.expiry<new Date(Date.now()+30*86400000).toISOString().slice(0,10)?'Expiring soon':'Good'):'—'}</td></tr>`).join('')}</tbody></table></section>`:''}<section class="panel catalogue-panel"`)};
const todayISO=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`},prettyDate=iso=>{const d=new Date(`${iso}T12:00:00`);return Number.isNaN(d.getTime())?iso:new Intl.DateTimeFormat('en',{day:'2-digit',month:'short',year:'numeric'}).format(d)};
function toISODate(value){const raw=String(value||'').trim();if(/^\d{4}-\d{2}-\d{2}$/.test(raw))return raw;const match=raw.match(/^(\d{1,2})\s+([A-Za-z]{3,9}),?\s+(\d{4})$/);if(match){const months=['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'],month=months.indexOf(match[2].slice(0,3).toLowerCase());if(month<0)return '';return `${match[3]}-${String(month+1).padStart(2,'0')}-${match[1].padStart(2,'0')}`}const d=new Date(raw);if(Number.isNaN(d.getTime()))return '';return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function posPage(){return `<div class="page-heading"><div><span class="section-kicker">CHECKOUT</span><h1>Sales / POS</h1><p>Record a sale, apply a discount, track paid and due amounts, then print a memo.</p></div></div><section class="panel settings-panel pos-workspace"><form id="pos-form"><div class="pos-form-heading"><span class="pos-step">01</span><div><h2>Sale details</h2><p>Add the customer, items and payment information.</p></div></div><div class="feature-form-grid"><label class="modal-field">Customer name<input name="customer" placeholder="Walk-in customer" required></label><label class="modal-field">Phone or email<input name="email" placeholder="Optional contact"></label><label class="modal-field">Scan / enter barcode<input id="pos-barcode" placeholder="Enter a product barcode"></label><label class="modal-field">Product<select name="product" required>${products.filter(p=>p.active!==false).map(p=>`<option value="${products.indexOf(p)}">${escapeHtml(p.name)} · ${money(p.price)} · ${p.stock} in stock</option>`).join('')}</select></label><label class="modal-field">Quantity<input name="qty" type="number" min="1" value="1" required></label><label class="modal-field">Discount (BDT)<input name="discount" type="number" min="0" step="0.01" placeholder="0"></label><label class="modal-field">Paid now (BDT)<input name="paid" type="number" min="0" step="0.01" placeholder="0"></label><label class="modal-field">Payment account<select name="account"><option>Cash</option><option>Bank</option></select></label></div><div class="pos-live-summary" id="pos-live-summary" aria-live="polite"><div><span>Unit price</span><b data-pos="unit">${money(products[0]?.price||0)}</b></div><div><span>Quantity</span><b data-pos="quantity">1</b></div><div><span>Subtotal</span><b data-pos="subtotal">${money(products[0]?.price||0)}</b></div><div><span>Discount</span><b data-pos="discount">${money(0)}</b></div><div class="pos-summary-total"><span>Payable total</span><b data-pos="total">${money(products[0]?.price||0)}</b></div><div><span>Paid</span><b data-pos="paid">${money(0)}</b></div><div class="pos-summary-due"><span>Remaining due</span><b data-pos="due">${money(products[0]?.price||0)}</b></div></div><div class="feature-actions"><button class="button-primary" type="submit">Save sale</button></div></form><aside class="pos-guide"><span class="pos-guide-icon">✓</span><span class="pos-guide-label">QUICK CHECKOUT</span><h3>Ready to ring up a sale?</h3><p>Complete these steps to save the transaction and update your stock.</p><ol><li>Choose a customer and product</li><li>Enter quantity and payment</li><li>Save the sale to record it</li></ol><div class="pos-guide-note">Stock changes after you save. You can print the memo afterward.</div></aside><div id="pos-receipt" class="feature-note">Select a product to create a sale memo.</div></section>`}
function updatePosSummary(){const form=document.querySelector('#pos-form'),summary=document.querySelector('#pos-live-summary');if(!form||!summary)return;const product=products[Number(form.elements.product.value)],unit=Number(product?.price)||0,quantity=Math.max(1,Math.floor(Number(form.elements.qty.value)||1)),subtotal=unit*quantity,discount=Math.min(subtotal,Math.max(0,Number(form.elements.discount.value)||0)),total=Math.max(0,subtotal-discount),paid=Math.min(total,Math.max(0,Number(form.elements.paid.value)||0)),values={unit,quantity,subtotal,discount,total,paid,due:total-paid};for(const [key,value] of Object.entries(values)){const target=summary.querySelector(`[data-pos="${key}"]`);if(target)target.textContent=key==='quantity'?String(value):money(value)}form.elements.discount.max=String(subtotal);form.elements.paid.max=String(total)}function purchasesPage(){return `<div class="page-heading"><div><span class="section-kicker">SUPPLY & STOCK</span><h1>Purchases</h1><p>Record supplier bills, stock received, paid amounts and balances due.</p></div></div><section class="panel settings-panel"><form id="purchase-form"><div class="feature-form-grid"><label class="modal-field">Supplier<input name="supplier" required placeholder="Supplier name"></label><label class="modal-field">Product<select name="product" required>${products.filter(p=>p.active!==false).map(p=>`<option value="${products.indexOf(p)}">${escapeHtml(p.name)} · stock ${p.stock}</option>`).join('')}</select></label><label class="modal-field">Quantity received<input name="qty" type="number" min="1" value="1" required></label><label class="modal-field">Unit cost (BDT)<input name="cost" type="number" min="0" step="0.01" required></label><label class="modal-field">Paid now (BDT)<input name="paid" type="number" min="0" step="0.01" value="0" required></label><label class="modal-field">Payment account<select name="account"><option>Cash</option><option>Bank</option></select></label></div><div class="feature-actions"><button class="button-primary" type="submit">Save purchase & update stock</button></div></form></section><section class="panel table-panel feature-table"><div class="table-title"><h3>Supplier ledger</h3></div>${purchases.length?`<table class="data-table"><thead><tr><th>SUPPLIER</th><th>PRODUCT</th><th>DATE</th><th>TOTAL</th><th>PAID</th><th>DUE</th></tr></thead><tbody>${purchases.map(x=>`<tr><td>${escapeHtml(x.supplier)}</td><td>${escapeHtml(x.product)}</td><td>${escapeHtml(x.date)}</td><td>${money(x.total)}</td><td>${money(x.paid)}</td><td>${money(x.total-x.paid)}</td></tr>`).join('')}</tbody></table>`:`<div class="empty-state"><strong>No purchases recorded</strong>Saved supplier balances will appear here.</div>`}</section>`}
function accountsPage(){const salesPaid=orders.filter(o=>o.status!=='Cancelled').reduce((s,o)=>s+Number(o.paidAmount??(o.status==='Paid'?o.total:0)),0),expensesPaid=expenses.reduce((s,x)=>s+Number(x.amount||0),0),purchasesPaid=purchases.reduce((s,x)=>s+Number(x.paid||0),0),supplierDue=purchases.reduce((s,x)=>s+Number(x.total||0)-Number(x.paid||0),0),customerDue=orders.filter(o=>o.status!=='Cancelled').reduce((s,o)=>s+Math.max(0,Number(o.total||0)-Number(o.paidAmount??(o.status==='Paid'?o.total:0))),0);return `<div class="page-heading"><div><span class="section-kicker">CASH FLOW</span><h1>Accounts</h1><p>Cash and bank balances, customer dues, supplier dues, income and expenses.</p></div></div><section class="metrics-grid">${metric(icons.sales,'Cash balance',money(accountBalances.cash),'opening balance + recorded payments')}${metric(icons.average,'Bank balance',money(accountBalances.bank),'opening balance + recorded payments')}${metric(icons.orders,'Customer dues',money(customerDue),'unpaid sales')}${metric(icons.customers,'Supplier dues',money(supplierDue),'unpaid purchases')}</section><section class="panel settings-panel"><h3>Opening balances</h3><p>Set the cash and bank amount you have before tracking transactions here.</p><form id="balance-form" class="feature-form-grid"><label class="modal-field">Cash on hand (BDT)<input name="cash" type="number" min="0" step="0.01" value="${Number(accountBalances.cash)||0}"></label><label class="modal-field">Bank balance (BDT)<input name="bank" type="number" min="0" step="0.01" value="${Number(accountBalances.bank)||0}"></label><div class="feature-actions"><button class="button-primary">Save balances</button></div></form></section><section class="summary-cards feature-table"><article class="panel summary-card"><small>Sales paid</small><strong>${money(salesPaid)}</strong></article><article class="panel summary-card"><small>Purchase payments</small><strong>${money(purchasesPaid)}</strong></article><article class="panel summary-card"><small>Expenses</small><strong>${money(expensesPaid)}</strong></article></section>`}
function reportsPage(){const salesOrders=orders.filter(o=>o.status!=='Cancelled'),gross=salesOrders.reduce((s,o)=>s+Number(o.total||0),0),cost=salesOrders.reduce((s,o)=>s+(o.lines||[]).reduce((n,l)=>n+Number(l.cost||0)*Number(l.qty||0),0),0),expenseTotal=expenses.reduce((s,x)=>s+Number(x.amount||0),0),profit=gross-cost-expenseTotal,top={};salesOrders.forEach(o=>(o.lines||[]).forEach(l=>top[l.name]=(top[l.name]||0)+Number(l.qty||0)));const rows=Object.entries(top).sort((a,b)=>b[1]-a[1]).slice(0,5);return `<div class="page-heading"><div><span class="section-kicker">SALES & PROFIT</span><h1>Reports</h1><p>Daily, monthly and yearly sales summaries from saved records.</p></div><button class="button-secondary" data-action="export">Export orders</button></div><section class="panel settings-panel"><div class="feature-form-grid"><label class="modal-field">Report period<select id="report-period"><option value="day">Today</option><option value="month" selected>This month</option><option value="year">This year</option></select></label><label class="modal-field">Date<input id="report-date" type="date" value="${todayISO()}"></label></div><div id="report-results" class="summary-cards feature-table">${reportSummary('month',todayISO())}</div><h3 class="feature-subheading">Top selling products</h3>${rows.length?`<table class="data-table"><thead><tr><th>PRODUCT</th><th>UNITS SOLD</th></tr></thead><tbody>${rows.map(([name,qty])=>`<tr><td>${escapeHtml(name)}</td><td>${qty}</td></tr>`).join('')}</tbody></table>`:`<p class="feature-note">Product-level sales appear after POS sales are recorded.</p>`}<p class="feature-note">Estimated profit = recorded sales − known item costs − recorded expenses. Older demo sales have no item cost details, so profit is incomplete.</p></section>`}
function reportSummary(period,date){const key=period==='day'?date:period==='month'?date.slice(0,7):date.slice(0,4),filtered=orders.filter(o=>o.status!=='Cancelled'&&toISODate(o.saleDate||o.date).startsWith(key)),sales=filtered.reduce((s,o)=>s+Number(o.total||0),0),cost=filtered.reduce((s,o)=>s+(o.lines||[]).reduce((n,l)=>n+Number(l.cost||0)*Number(l.qty||0),0),0),paid=filtered.reduce((s,o)=>s+Number(o.paidAmount??(o.status==='Paid'?o.total:0)),0),periodExpenses=expenses.filter(x=>{const iso=toISODate(x.date);if(!iso)return false;return (period==='day'?iso:period==='month'?iso.slice(0,7):iso.slice(0,4))===key}).reduce((s,x)=>s+Number(x.amount||0),0);return `<article class="panel summary-card"><small>Sales · ${period}</small><strong>${money(sales)}</strong></article><article class="panel summary-card"><small>Orders</small><strong>${filtered.length}</strong></article><article class="panel summary-card"><small>Payments received</small><strong>${money(paid)}</strong></article><article class="panel summary-card"><small>Estimated net profit</small><strong>${money(sales-cost-periodExpenses)}</strong></article>`}
customersPage=function(){const map=new Map();orders.filter(o=>o.status!=='Cancelled').forEach(o=>{const c=map.get(o.email)||{name:o.name,email:o.email,count:0,spend:0,due:0,last:o.date};c.count++;c.spend+=Number(o.total||0);c.due+=Math.max(0,Number(o.total||0)-Number(o.paidAmount??(o.status==='Paid'?o.total:0)));map.set(o.email,c)});const list=[...map.values()];return `<div class="page-heading"><div><span class="section-kicker">CUSTOMER BOOK</span><h1>Customers</h1><p>Purchase history and outstanding customer balances.</p></div></div><section class="panel table-panel"><table class="data-table"><thead><tr><th>CUSTOMER</th><th>CONTACT</th><th>LAST ORDER</th><th>ORDERS</th><th>SPEND</th><th>DUE</th></tr></thead><tbody>${list.map(c=>`<tr><td>${escapeHtml(c.name)}</td><td>${escapeHtml(c.email||'—')}</td><td>${escapeHtml(c.last)}</td><td>${c.count}</td><td>${money(c.spend)}</td><td>${money(c.due)}</td></tr>`).join('')}</tbody></table></section>`};
const pages={dashboard,orders:ordersPage,pos:posPage,purchases:purchasesPage,products:productsPage,customers:customersPage,expenses:expensesPage,accounts:accountsPage,reports:reportsPage,settings:settingsPage};
function renderPage(page){if(!pages[page])page='dashboard';pageContent.innerHTML=pages[page]();stabilizeSelectValues(pageContent);if(page==='pos')updatePosSummary();document.querySelectorAll('.nav-link').forEach(a=>a.classList.toggle('active',a.dataset.page===page));document.querySelector('#breadcrumb-page').textContent=page.charAt(0).toUpperCase()+page.slice(1);document.querySelector('.nav-count').textContent=orders.length;document.querySelector('#sidebar').classList.remove('open');document.querySelector('#sidebar-backdrop').classList.remove('is-visible');if(page==='orders'){document.querySelector('#order-search').addEventListener('input',filterOrders);document.querySelector('#status-filter').addEventListener('change',filterOrders);pageContent.querySelectorAll('[data-status-shortcut]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#status-filter').value=button.dataset.statusShortcut;pageContent.querySelectorAll('.status-tile').forEach(tile=>tile.classList.toggle('selected',tile===button));filterOrders()}))}if(page==='products'){document.querySelector('#product-search').addEventListener('input',filterProducts);document.querySelector('#category-filter').addEventListener('change',filterProducts);document.querySelector('#stock-filter').addEventListener('change',filterProducts)}if(page==='expenses'){document.querySelector('#expense-search').addEventListener('input',filterExpenses);document.querySelector('#expense-category').addEventListener('change',filterExpenses)}const period=document.querySelector('#chart-period');if(period)period.addEventListener('change',e=>notify(`Showing revenue for ${e.target.value.toLowerCase()}.`))}
function filterOrders(){const query=document.querySelector('#order-search').value.toLowerCase(),status=document.querySelector('#status-filter').value;const filtered=orders.filter(o=>(!status||o.status===status)&&`${o.id} ${o.name} ${o.email}`.toLowerCase().includes(query));document.querySelector('#orders-table').innerHTML=orderTable(filtered,Infinity,true)+`<div class="table-footer"><span id="order-count">${filtered.length} matching sample orders</span><span>Demo records · all dates</span></div>`}
function filterProducts(){const q=document.querySelector('#product-search').value.toLowerCase(),category=document.querySelector('#category-filter').value,stock=document.querySelector('#stock-filter').value,archived=stock==='archived',filtered=products.filter(p=>(archived?p.active===false:p.active!==false)&&(!category||p.category===category)&&(!stock||archived||stock==='low'&&Number(p.stock)<10||stock==='available'&&Number(p.stock)>0||stock==='empty'&&Number(p.stock)===0)&&`${p.name} ${p.category}`.toLowerCase().includes(q));document.querySelector('#product-grid').innerHTML=productCards(filtered)}function filterExpenses(){const q=document.querySelector('#expense-search').value.toLowerCase(),category=document.querySelector('#expense-category').value,filtered=expenses.filter(x=>(!category||x.category===category)&&`${x.description} ${x.category} ${x.method}`.toLowerCase().includes(q));document.querySelector('#expense-table').innerHTML=expenseTable(filtered)}
function exportOrders(){const csv=[['Order','Customer','Email','Date','Items','Total BDT','Status'],...orders.map(o=>[o.id,o.name,o.email,o.date,o.items,o.total,o.status])].map(r=>r.map(x=>`"${String(x).replaceAll('"','""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='probashi-store-orders.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Your orders report has been downloaded.')}
document.querySelector('#main-nav').addEventListener('click',e=>{const link=e.target.closest('[data-page]');if(link){e.preventDefault();location.hash=link.dataset.page;renderPage(link.dataset.page)}});window.addEventListener('hashchange',()=>{if(!appView.classList.contains('hidden'))renderPage(location.hash.slice(1)||'dashboard')});
