function openModal(mode,index=-1){modalMode=mode.replace('edit-','');modalRecordIndex=index;const editing=mode.startsWith('edit-'),record=editing?(modalMode==='product'?products[index]:expenses[index]):{};const title={order:'Create an order',product:editing?'Edit product':'Add a product',expense:editing?'Edit expense':'Add an expense'}[modalMode];document.querySelector('#modal-title').textContent=title;document.querySelector('#record-form').classList.remove('modal-readonly');document.querySelector('#record-form button[type="submit"]').classList.remove('hidden');document.querySelector('#modal-cancel').textContent='Cancel';const specs={order:[['customer','Customer name','text'],['email','Email address','email'],['total','Order total (BDT)','number'],['items','Number of items','number']],product:[['name','Product name','text'],['category','Category','text'],['price','Selling price (BDT)','number'],['cost','Unit cost (BDT)','number'],['stock','Stock quantity','number'],['barcode','Barcode','text'],['expiry','Expiry date','date']],expense:[['description','Description','text'],['category','Category','text'],['amount','Amount (BDT)','number'],['method','Payment method','text']]};document.querySelector('#modal-fields').innerHTML=specs[modalMode].map(([id,label,type])=>`<label class="modal-field">${label}<input name="${id}" type="${type}" value="${escapeHtml(record?.[id]??'')}" ${type==='number'?`min="0" step="${id==='stock'?'1':'0.01'}"`:''} ${id==='name'||id==='category'||id==='price'||id==='stock'||id==='description'||id==='amount'||id==='method'?'required':''}></label>`).join('');modal.classList.remove('hidden');modal.querySelector('input')?.focus()}
function openOrderEdit(index){const o=orders[index];if(!o)return;modalMode='order-edit';modalRecordIndex=index;document.querySelector('#modal-title').textContent=`Edit order ${o.id}`;const form=document.querySelector('#record-form');form.classList.remove('modal-readonly');form.querySelector('button[type="submit"]').classList.remove('hidden');document.querySelector('#modal-cancel').textContent='Cancel';document.querySelector('#modal-fields').innerHTML=`<label class="modal-field">Customer name<input name="customer" maxlength="100" value="${escapeHtml(o.name)}" required></label><label class="modal-field">Email address<input name="email" type="email" value="${escapeHtml(o.email)}"></label><label class="modal-field">Number of items<input name="items" type="number" min="1" step="1" value="${Number(o.items)||1}" required></label><label class="modal-field">Order total (BDT)<input name="total" type="number" min="0.01" step="0.01" value="${Number(o.total)||0}" required></label>`;modal.classList.remove('hidden');modal.querySelector('input')?.focus()}
function openOrderDetails(index){const o=orders[index];if(!o)return;modalMode='order-detail';modalRecordIndex=index;document.querySelector('#modal-title').textContent=`Order ${o.id}`;const form=document.querySelector('#record-form');form.classList.add('modal-readonly');form.querySelector('button[type="submit"]').classList.add('hidden');document.querySelector('#modal-cancel').textContent='Close';const fields=document.querySelector('#modal-fields');fields.innerHTML=`<div class="order-detail-head"><span class="customer-avatar">${escapeHtml(o.initials)}</span><div><b>${escapeHtml(o.name)}</b><small>${escapeHtml(o.email)}</small></div></div><div class="detail-grid"><div><small>ORDER DATE</small><b>${escapeHtml(o.date)}</b></div><div><small>ITEM COUNT</small><b>${o.items} ${o.items===1?'item':'items'}</b></div><div><small>ORDER TOTAL</small><b>${money(o.total)}</b></div><div><small>ORDER STATUS</small><select id="detail-order-status" class="filter-select">${['Pending','Paid','Shipped','Delivered','Cancelled'].map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></div></div><p class="detail-note">Sample order detail · connect a store database later to load real products and delivery updates.</p>`;stabilizeSelectValues(fields);modal.classList.remove('hidden')}
function closeModal(){modal.classList.add('hidden');document.querySelector('#record-form').classList.remove('modal-readonly');document.querySelector('#record-form button[type="submit"]').classList.remove('hidden');document.querySelector('#modal-cancel').textContent='Cancel'}
document.querySelector('#modal-close').addEventListener('click',closeModal);document.querySelector('#modal-cancel').addEventListener('click',closeModal);modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeSidebar()}});
modal.addEventListener('change',e=>{if(e.target.id==='detail-order-status'){const o=orders[modalRecordIndex];if(!o)return;o.status=e.target.value;persistData('orders',orders);const current=location.hash.slice(1)||'dashboard';renderPage(current);openOrderDetails(modalRecordIndex);notify('Order status updated for this demo record.')}});
pageContent.addEventListener('click',e=>{const trigger=e.target.closest('[data-action]');if(!trigger)return;const {action,index}=trigger.dataset;if(action==='export')exportOrders();if(action==='orders'){location.hash='orders';renderPage('orders')}if(action==='new-order')openModal('order');if(action==='add-product')openModal('product');if(action==='edit-product')openModal('edit-product',Number(index));if(action==='add-expense')openModal('expense');if(action==='edit-expense')openModal('edit-expense',Number(index));if(action==='view-order')openOrderDetails(Number(index));if(action==='edit-order')openOrderEdit(Number(index));if(action==='save-settings'){const name=document.querySelector('[aria-label="Store name"]'),email=document.querySelector('[aria-label="Contact email"]');if(!name.value.trim()){notify('Enter a store name before saving.');name.focus();return}if(!email.checkValidity()){notify('Enter a valid contact email before saving.');email.focus();return}storeSettings={storeName:name.value.trim(),contactEmail:email.value.trim(),currency:document.querySelector('[aria-label="Currency"]').value,timezone:document.querySelector('[aria-label="Timezone"]').value};localStorage.setItem('probashi-store-settings',JSON.stringify(storeSettings));localStorage.setItem('probashi-store-name',storeSettings.storeName);notify('Store preferences saved.')}});
const sidebar=document.querySelector('#sidebar'),sidebarBackdrop=document.querySelector('#sidebar-backdrop');function closeSidebar(){sidebar.classList.remove('open');sidebarBackdrop.classList.remove('is-visible')}document.querySelector('#mobile-menu').addEventListener('click',()=>{sidebar.classList.add('open');sidebarBackdrop.classList.add('is-visible')});document.querySelector('#sidebar-close').addEventListener('click',closeSidebar);sidebarBackdrop.addEventListener('click',closeSidebar);document.querySelector('#notification-button').addEventListener('click',()=>notify('You’re all caught up.'));document.querySelector('#support-button').addEventListener('click',()=>notify('Email us at hello@probashi.store'));document.querySelector('#profile-button').addEventListener('click',logout);document.querySelector('#top-avatar').addEventListener('click',logout);
if(localStorage.getItem('probashiSignedIn')==='true')enterApp();
pageContent.addEventListener('submit',e=>{
  if(!['pos-form','purchase-form','balance-form'].includes(e.target.id))return;e.preventDefault();const v=Object.fromEntries(new FormData(e.target).entries()),date=todayISO();
  if(e.target.id==='balance-form'){accountBalances={cash:Number(v.cash)||0,bank:Number(v.bank)||0};localStorage.setItem('probashi-balances',JSON.stringify(accountBalances));renderPage('accounts');notify('Opening balances saved.');return}
  if(e.target.id==='purchase-form'){const p=products[Number(v.product)],qty=Number(v.qty),total=qty*Number(v.cost),paid=Math.min(total,Number(v.paid));if(!p)return;p.stock=Number(p.stock)+qty;p.cost=Number(v.cost);purchases.unshift({supplier:v.supplier.trim(),product:p.name,productIndex:Number(v.product),qty,cost:Number(v.cost),total,paid,date:prettyDate(date)});persistData('products',products);persistData('purchases',purchases);accountBalances[v.account.toLowerCase()]=Number(accountBalances[v.account.toLowerCase()]||0)-paid;localStorage.setItem('probashi-balances',JSON.stringify(accountBalances));renderPage('purchases');notify(`Purchase saved. Supplier due: ${money(total-paid)}.`);return}
  const p=products[Number(v.product)],qty=Math.floor(Number(v.qty));if(!p)return;if(!Number.isFinite(qty)||qty<1){notify('Enter a valid quantity.');return}if(qty>Number(p.stock)){notify(`Only ${p.stock} units are in stock.`);return}const subtotal=Number(p.price)*qty,discount=Number(v.discount)||0;if(discount<0||discount>subtotal){notify(`Discount cannot exceed the subtotal of ${money(subtotal)}.`);return}const total=subtotal-discount,paid=Number(v.paid)||0;if(paid<0||paid>total){notify(`Paid amount cannot exceed the payable total of ${money(total)}.`);return}const name=v.customer.trim();if(!name){notify('Enter a customer name.');return}const email=v.email.trim()||`${name.toLowerCase().replace(/[^a-z0-9]+/g,'.')}@walkin.local`,next=Math.max(1040,...orders.map(o=>Number(o.id.replace(/\D/g,''))||0))+1;const sale={id:`#PS-${next}`,name,email,initials:initial(name),color:'#eee8d8',date:prettyDate(date),saleDate:date,items:qty,subtotal,discount,total,paidAmount:paid,status:paid>=total?'Paid':'Pending',lines:[{name:p.name,qty,price:Number(p.price),cost:Number(p.cost)||0}]};orders.unshift(sale);p.stock=Number(p.stock)-qty;persistData('orders',orders);persistData('products',products);accountBalances[v.account.toLowerCase()]=Number(accountBalances[v.account.toLowerCase()]||0)+paid;localStorage.setItem('probashi-balances',JSON.stringify(accountBalances));renderPage('pos');document.querySelector('#pos-receipt').innerHTML=`<div class="pos-save-confirmation"><div class="pos-save-heading"><span class="pos-save-check" aria-hidden="true">✓</span><div><strong>বিক্রি সংরক্ষণ হয়েছে</strong><small>মেমো ${sale.id}</small></div></div><p class="pos-save-customer">ক্রেতা: <b>${escapeHtml(sale.name)}</b></p><button class="pos-print-button" type="button" data-action="print-last"><span aria-hidden="true">⎙</span> মেমো প্রিন্ট</button></div>`;notify(`Sale saved. Customer due: ${money(total-paid)}.`)
});
pageContent.addEventListener('input',e=>{if(e.target.id==='pos-barcode'){const match=products.findIndex(p=>p.active!==false&&p.barcode&&p.barcode===e.target.value.trim());if(match>=0)document.querySelector('#pos-form [name="product"]').value=String(match)}if(e.target.closest('#pos-form'))updatePosSummary()});pageContent.addEventListener('change',e=>{if(e.target.closest('#pos-form'))updatePosSummary()});
pageContent.addEventListener('change',e=>{if(e.target.id==='report-period'||e.target.id==='report-date'){const period=document.querySelector('#report-period').value,date=document.querySelector('#report-date').value;document.querySelector('#report-results').innerHTML=reportSummary(period,date)}});
pageContent.addEventListener('click',e=>{
  if(!e.target.closest('[data-action="print-last"]'))return;
  const o=orders.find(x=>x.lines);if(!o){notify('No POS memo to print yet.');return}
  const total=Number(o.total)||0,subtotal=Number(o.subtotal??(o.lines||[]).reduce((sum,line)=>sum+(Number(line.price)||0)*(Number(line.qty)||0),total)),discount=Number(o.discount??Math.max(0,subtotal-total))||0,paid=Math.min(total,Math.max(0,Number(o.paidAmount??(o.status==='Paid'?total:0))||0)),due=Math.max(0,total-paid);
  const bn=value=>Number(value||0).toLocaleString('en-US',{maximumFractionDigits:2}),memoMoney=value=>'\u09F3 '+bn(value),iso=toISODate(o.saleDate||o.date),dateLabel=iso?new Date(`${iso}T12:00:00`).toLocaleDateString('bn-BD',{year:'numeric',month:'long',day:'numeric'}):escapeHtml(o.date);
  const lines=(o.lines||[]).map((line,index)=>`<tr><td>${bn(index+1)}</td><td>${escapeHtml(line.name)}</td><td>${bn(line.qty)}</td><td>${memoMoney(line.price)}</td><td>${memoMoney((Number(line.qty)||0)*(Number(line.price)||0))}</td></tr>`).join('');
  const status=due>0?'বাকি আছে':'পরিশোধিত';
  const printPage=document.createElement('div');printPage.className='print-target';printPage.innerHTML=`<article class="receipt">
    <header class="receipt-header"><div class="receipt-brand-mark">${escapeHtml((storeSettings.storeName||'P').trim().slice(0,1).toUpperCase())}</div><div class="receipt-brand"><h1>${escapeHtml(storeSettings.storeName||'Probashi Store')}</h1><p>আপনার বিশ্বস্ত কেনাকাটার ঠিকানা</p></div><div class="receipt-title"><span>SALES RECEIPT</span><strong>বিক্রয় মেমো</strong></div></header>
    <div class="receipt-rule"></div><section class="receipt-meta"><div><small>মেমো নম্বর</small><b>${escapeHtml(o.id)}</b></div><div><small>তারিখ</small><b>${dateLabel}</b></div><div><small>পেমেন্ট অবস্থা</small><b class="receipt-status ${due>0?'is-due':''}">${status}</b></div></section>
    <section class="receipt-customer"><div><small>বিল করা হয়েছে</small><strong>${escapeHtml(o.name)}</strong>${o.email&&!o.email.endsWith('@walkin.local')?`<span>${escapeHtml(o.email)}</span>`:''}</div><span class="receipt-customer-icon" aria-hidden="true">●</span></section>
    <table class="receipt-items"><thead><tr><th>নং</th><th>পণ্যের বিবরণ</th><th>পরিমাণ</th><th>একক মূল্য</th><th>মোট</th></tr></thead><tbody>${lines}</tbody></table>
    <section class="receipt-bottom"><div class="receipt-totals"><div><span>সাবটোটাল</span><b>${memoMoney(subtotal)}</b></div><div><span>ছাড়</span><b>− ${memoMoney(discount)}</b></div><div class="receipt-total"><span>সর্বমোট</span><b>${memoMoney(total)}</b></div><div class="receipt-paid"><span>পরিশোধ করেছেন</span><b>${memoMoney(paid)}</b></div><div class="receipt-due ${due>0?'has-due':''}"><span>বাকি টাকা</span><strong>${memoMoney(due)}</strong></div></div></section>
    <footer class="receipt-footer"><span>ক্রেতার স্বাক্ষর</span><span>বিক্রেতার স্বাক্ষর</span></footer><div class="receipt-footer-note">${escapeHtml(storeSettings.storeName||'Probashi Store')} · ধন্যবাদ আমাদের সাথে থাকার জন্য</div>
  </article>`;
  document.body.appendChild(printPage);window.print();printPage.remove();
});

function expenseAccount(method){return /bank|mobile|card/i.test(method||'')?'bank':'cash'}
function saveExpenseCollection(nextExpenses,nextBalances){const oldExpenses=localStorage.getItem('probashi-expenses'),oldBalances=localStorage.getItem('probashi-balances');try{localStorage.setItem('probashi-expenses',JSON.stringify(nextExpenses));localStorage.setItem('probashi-balances',JSON.stringify(nextBalances))}catch{try{oldExpenses===null?localStorage.removeItem('probashi-expenses'):localStorage.setItem('probashi-expenses',oldExpenses);oldBalances===null?localStorage.removeItem('probashi-balances'):localStorage.setItem('probashi-balances',oldBalances)}catch{}notify('Could not save expense changes. Browser storage may be full or unavailable.');return false}expenses=nextExpenses;accountBalances=nextBalances;return true}

document.addEventListener('submit',event=>{
  if(event.target.id!=='record-form')return;
  if(modalMode==='product'){
    event.preventDefault();event.stopImmediatePropagation();
    const data=new FormData(event.target),index=modalRecordIndex,existing=index>=0?products[index]:null,name=String(data.get('name')||'').trim(),category=String(data.get('category')||'').trim(),price=Number(data.get('price')),cost=Number(data.get('cost')||0),stock=Number(data.get('stock'))||0,barcode=String(data.get('barcode')||'').trim(),expiry=String(data.get('expiry')||'').trim();
    if(!name||!category||!Number.isFinite(price)||price<=0||!Number.isFinite(cost)||cost<0||!Number.isFinite(stock)||stock<0||!Number.isInteger(stock)){notify('Enter a product name, category, valid price, cost, and stock quantity.');return}
    if(barcode&&products.some((product,i)=>i!==index&&product.barcode===barcode)){notify('That barcode is already assigned to another product.');return}
    const product={...(existing||{}),name,category,price,cost,stock,barcode,expiry,icon:existing?.icon||'📦',active:existing?.active!==false},next=products.slice();if(existing)next[index]=product;else next.push(product);
    try{localStorage.setItem('probashi-products',JSON.stringify(next))}catch{notify('Could not save the product. Browser storage may be full or unavailable.');return}
    products=next;closeModal();renderPage('products');notify(existing?'Product updated successfully.':'Product added successfully.');return;
  }
  if(modalMode==='expense'){
    event.preventDefault();event.stopImmediatePropagation();
    const data=new FormData(event.target),index=modalRecordIndex,existing=index>=0?expenses[index]:null,description=String(data.get('description')||'').trim(),category=String(data.get('category')||'').trim(),method=String(data.get('method')||'').trim(),amount=Number(data.get('amount'));
    if(!description||!category||!method||!Number.isFinite(amount)||amount<=0){notify('Enter an expense description, category, payment method, and valid amount.');return}
    const record={...(existing||{}),description,category,method,amount,date:existing?.date||prettyDate(todayISO())},next=expenses.slice();if(existing)next[index]=record;else next.unshift(record);
    const balances={...accountBalances};if(existing)balances[expenseAccount(existing.method)]=Number(balances[expenseAccount(existing.method)]||0)+Number(existing.amount||0);const account=expenseAccount(method);balances[account]=Number(balances[account]||0)-amount;
    if(!saveExpenseCollection(next,balances))return;
    closeModal();renderPage('expenses');notify(existing?'Expense updated successfully.':'Expense saved successfully.');
  }
});

pageContent.addEventListener('click',event=>{
  const button=event.target.closest('[data-action="archive-product"],[data-action="restore-product"],[data-action="delete-expense"]');if(!button)return;
  const index=Number(button.dataset.index),action=button.dataset.action,english=localStorage.getItem('probashi-language')==='en';
  if(action==='delete-expense'){
    const expense=expenses[index];if(!expense)return;
    const account=expenseAccount(expense.method),prompt=english?`Delete "${expense.description}"? The ${account} balance will be adjusted.`:`“${expense.description}” খরচটি মুছবেন? এতে ${account==='bank'?'ব্যাংক':'নগদ'} ব্যালেন্স সমন্বয় হবে।`;
    if(!confirm(prompt))return;
    const next=expenses.filter((_,i)=>i!==index),balances={...accountBalances};balances[account]=Number(balances[account]||0)+Number(expense.amount||0);
    if(!saveExpenseCollection(next,balances))return;
    renderPage('expenses');notify(english?'Expense deleted and account balance adjusted.':'খরচ মুছে হিসাবের ব্যালেন্স সমন্বয় করা হয়েছে।');return;
  }
  const product=products[index];if(!product)return;
  const archiving=action==='archive-product';
  const prompt=english?`Archive "${product.name}"? It will be hidden from POS while its history and stock remain saved.`:`“${product.name}” আর্কাইভ করবেন? পণ্যটি POS থেকে লুকাবে, তবে ইতিহাস ও স্টক সংরক্ষিত থাকবে।`;
  if(archiving&&!confirm(prompt))return;
  const next=products.slice();next[index]={...product,active:!archiving};
  try{localStorage.setItem('probashi-products',JSON.stringify(next))}catch{notify('Could not update this product. Browser storage may be full or unavailable.');return}
  products=next;renderPage('products');notify(english?(archiving?'Product archived and hidden from POS.':'Product restored to POS.'):(archiving?'পণ্য আর্কাইভ করা হয়েছে, POS-এ দেখাবে না।':'পণ্য POS-এ ফিরিয়ে আনা হয়েছে।'));
});